    public static void Run()
    {
        string root=Path.GetFullPath("work/bedrock-isolation-checks/"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
        string live=Path.Combine(root,"Windows-data"),owned=Path.Combine(root,"instances"),journal=Path.Combine(root,"redirect.json"),one=Path.Combine(owned,"1.18","user-data"),two=Path.Combine(owned,"1.21","user-data");Directory.CreateDirectory(Path.Combine(live,"minecraftWorlds","original"));Directory.CreateDirectory(Path.Combine(live,"empty-directory"));File.WriteAllText(Path.Combine(live,"minecraftWorlds","original","level.dat"),"original-world");File.WriteAllText(Path.Combine(live,"options.txt"),"original-settings");
