        string failedLive=Path.Combine(root,"failed-live"),failedJournal=Path.Combine(root,"failed.json");Directory.CreateDirectory(failedLive);File.WriteAllText(Path.Combine(failedLive,"original"),"recoverable");int attempts=0;var failed=new BedrockDataLink(failedLive,owned,failedJournal,(path,target)=>{if(++attempts==2)throw new IOException("injected link creation failure");DirectoryJunction.Create(path,target);});Rejected(()=>failed.Activate(one),"actual link failure after a successful preflight is reported");Check(new DirectoryInfo(failedLive).LinkTarget==null&&File.ReadAllText(Path.Combine(failedLive,"original"))=="recoverable"&&!File.Exists(failedJournal),"first activation failure rolls original directory back and permits a clean retry");var retry=new BedrockDataLink(failedLive,owned,failedJournal);retry.Activate(one);attempts=0;var failedSwitch=new BedrockDataLink(failedLive,owned,failedJournal,(path,target)=>{if(++attempts==2)throw new IOException("injected switch failure");DirectoryJunction.Create(path,target);});Rejected(()=>failedSwitch.Activate(two),"version switch failure is reported");Check(File.ReadAllText(Path.Combine(failedLive,"options.txt"))=="version-one","failed switch restores the previously active instance link");retry.Restore();
